package com.primehr.performancemanagement.infrastructure;import com.primehr.performancemanagement.domain.PerformanceManagementTeamMember;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.time.*;import java.util.*;
public interface PerformanceManagementTeamMemberRepository extends JpaRepository<PerformanceManagementTeamMember,String>{List<PerformanceManagementTeamMember>findByAgencyIdAndPmtIdOrderByEffectiveFromAscRoleAscEmployeeNoAsc(String agency,String pmt);void deleteByAgencyIdAndPmtId(String agency,String pmt);@Query("select count(m)>0 from PerformanceManagementTeamMember m where m.agencyId=:agency and upper(m.employeeNo)=upper(:employeeNo) and m.effectiveFrom<=:day and (m.effectiveTo is null or m.effectiveTo>=:day) and m.pmtId in (select t.id from PerformanceManagementTeam t where t.agencyId=:agency and t.status='ACTIVE' and t.effectiveFrom<=:day and (t.effectiveTo is null or t.effectiveTo>=:day))")boolean isEffectiveMember(@Param("agency")String agency,@Param("employeeNo")String employeeNo,@Param("day")LocalDate day);}
